async function loadData() {
  const res = await fetch('/wheel/data');
  if (!res.ok) { alert('讀取名單失敗，請重新整理'); return; }
  const data = await res.json();
  roster = data.roster;
  winners = data.winners;
  prizes = data.prizes;
  renderWinners();
  renderPrizeSelect();
  drawWheel();
  updateSpinAvailability();
}

function renderPrizeSelect() {
  const select = document.getElementById('prizeSelect');
  const textInput = document.getElementById('prizeInput');
  const noPrizeNote = document.getElementById('noPrizeNote');

  if (prizes.length === 0) {
    select.style.display = 'none';
    noPrizeNote.style.display = 'block';
    textInput.style.display = 'block';
    return;
  }
  noPrizeNote.style.display = 'none';
  select.style.display = 'block';
  textInput.style.display = 'none';

  const available = prizes.filter(p => p.remaining > 0);
  if (available.length === 0) {
    select.innerHTML = '<option value="">獎品都發完了</option>';
    return;
  }
  select.innerHTML = available.map(p =>
    `<option value="${p.id}">${escapeHtml(p.name)}（剩 ${p.remaining}）</option>`
  ).join('');
}

function togglePrizeEditor() {
  const editor = document.getElementById('prizeEditor');
  const isShowing = editor.style.display !== 'none';
  if (!isShowing) {
    document.getElementById('prizeEditorText').value =
      prizes.map(p => `${p.name} ${p.total}`).join('\n');
  }
  editor.style.display = isShowing ? 'none' : 'block';
}

async function savePrizes() {
  const text = document.getElementById('prizeEditorText').value;
  const res = await fetch('/wheel/prizes/set', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({text}),
  });
  const data = await res.json();
  if (!data.ok) { alert('儲存失敗：' + (data.error || '未知錯誤')); return; }
  document.getElementById('prizeEditor').style.display = 'none';
  await loadData();
}

