function spin() {
  if (isSpinning || roster.length === 0) return;
  if (prizes.length > 0 && !document.getElementById('prizeSelect').value) {
    alert('獎品都發完了，請重置或設定新的獎品清單');
    return;
  }
  isSpinning = true;
  updateSpinAvailability();
  spinAngleStart = Math.random() * 10 + 10;
  spinTime = 0;
  spinTimeTotal = Math.random() * 3000 + 4000;
  rotateWheel();
}

function rotateWheel() {
  spinTime += 30;
  if (spinTime >= spinTimeTotal) { stopRotateWheel(); return; }
  const spinAngle = spinAngleStart - (spinAngleStart * (spinTime / spinTimeTotal));
  startAngle += (spinAngle * Math.PI / 180);
  drawWheel();
  requestAnimationFrame(rotateWheel);
}

async function stopRotateWheel() {
  isSpinning = false;
  const degrees = startAngle * 180 / Math.PI + 90;
  const arcd = 360 / roster.length;
  const index = Math.floor((360 - degrees % 360) / arcd) % roster.length;
  const winner = roster[index];

  let payload = {attendee_id: winner.id};
  if (prizes.length > 0) {
    payload.prize_id = document.getElementById('prizeSelect').value;
  } else {
    payload.prize = document.getElementById('prizeInput').value.trim();
  }
  const res = await fetch('/wheel/winner', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(payload),
  });
  const data = await res.json();
  if (!data.ok) {
    alert(data.error || '記錄中獎失敗，請重新整理頁面再試一次');
    isSpinning = false;
    await loadData();
    return;
  }
  const wonPrizeName = prizes.length > 0
    ? (prizes.find(p => String(p.id) === String(payload.prize_id))?.name || '')
    : payload.prize;
  showResult(winner.name, wonPrizeName);
  await loadData();
}

function showResult(name, prize) {
  const randomMsg = funMessages[Math.floor(Math.random() * funMessages.length)];
  document.getElementById('resultMessage').innerText = randomMsg;
  document.getElementById('winnerName').innerText = name + (prize ? `　（${prize}）` : '');
  document.getElementById('resultModal').classList.add('show');
}

function closeModal() {
  document.getElementById('resultModal').classList.remove('show');
  document.getElementById('prizeInput').value = '';
}

async function resetWheel() {
  if (!confirm('確定要清空本場所有中獎紀錄嗎？清空後所有已簽到的人都可以重新被抽中。')) return;
  const res = await fetch('/wheel/reset', {method: 'POST'});
  const data = await res.json();
  if (!data.ok) { alert('重置失敗：' + (data.error || '未知錯誤')); return; }
  await loadData();
}

