async function spin() {
  if (isSpinning) return;

  // 送出抽獎前，先問一次資料庫有沒有新簽到的人，不要背景一直輪詢——
  // 只更新名單本身，不動獎品下拉選單（避免洗掉主持人剛選好的獎項）
  const res = await fetch('/wheel/data');
  if (res.ok) {
    const data = await res.json();
    roster = data.roster;
    winners = data.winners;
    renderWinners();
    drawWheel();
  }

  if (isSpinning || roster.length === 0) { updateSpinAvailability(); return; }
  if (prizes.length > 0 && !document.getElementById('prizeSelect').value) {
    alert('獎品都發完了，請重置或設定新的獎品清單');
    return;
  }
  isSpinning = true;
  updateSpinAvailability();
  spinAngleStart = Math.random() * 10 + 10;
  spinTime = 0;
  spinTimeTotal = Math.random() * 3000 + 4000;
  rotateWheel();
}

